examples.query:
SELECT ?catalog ?type (COUNT(?work) AS ?records) WHERE {
  ?catalog a dcat:Catalog ; dcterms:title ?title ; dcat:record/foaf:primaryTopic ?work .
  ?work a ?type .
} GROUP BY ?catalog ?type ORDER BY ?catalog DESC(?records)

SELECT ?name (COUNT(?work) AS ?works) WHERE {
  ?work schema:author ?person . ?person schema:name ?name .
} GROUP BY ?name ORDER BY DESC(?works) LIMIT 15

SELECT ?name ?work WHERE {
  ?work schema:conditionsOfAccess "openAccess" ; schema:name ?name .
  FILTER NOT EXISTS { ?work schema:license ?l }
} LIMIT 25

SELECT ?licence (COUNT(?work) AS ?works) WHERE {
  ?work schema:license ?licence .
} GROUP BY ?licence ORDER BY DESC(?works)

SELECT ?score ?name ?oai WHERE {
  ?rec ml:qualityScore ?score ; foaf:primaryTopic ?work ; dcterms:identifier ?oai .
  ?work schema:name ?name .
} ORDER BY ?score LIMIT 15

SELECT ?name (COUNT(DISTINCT ?catalog) AS ?repositories) WHERE {
  ?work schema:author ?p ; schema:includedInDataCatalog ?catalog . ?p schema:name ?name .
} GROUP BY ?name HAVING (COUNT(DISTINCT ?catalog) > 1) LIMIT 25
